def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(r"\s*(<=|>=|<>|[A-Z]+[0-9]+|[A-Z]+|[0-9]+|[()+\-*/,:=<>])")
    precedence = {"=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
                  "+": 1, "-": 1, "*": 2, "/": 2, "u-": 3}

    def parse(formula):
        tokens = token_pattern.findall(formula)
        operands = []
        operators = []
        expect_operand = True
        i = 0

        def reduce_operator():
            op = operators.pop()
            if op == "u-":
                operands.append(("unary", operands.pop()))
            else:
                right = operands.pop()
                left = operands.pop()
                operands.append(("binary", op, left, right))

        while i < len(tokens):
            token = tokens[i]

            if token.isdigit():
                operands.append(("number", int(token)))
                expect_operand = False
            elif token in ("SUM", "MIN", "MAX", "IF"):
                operators.append(("function", token))
                expect_operand = True
            elif token == "(":
                if operators and isinstance(operators[-1], tuple) and operators[-1][0] == "function":
                    function = operators.pop()[1]
                    operators.append(["(", function, 0])
                else:
                    operators.append(["(", None, 0])
                expect_operand = True
            elif token == ",":
                while not isinstance(operators[-1], list):
                    reduce_operator()
                operators[-1][2] += 1
                expect_operand = True
            elif token == ")":
                while not isinstance(operators[-1], list):
                    reduce_operator()
                _, function, commas = operators.pop()
                if function is not None:
                    count = commas + 1
                    args = operands[-count:]
                    del operands[-count:]
                    operands.append(("function", function, args))
                expect_operand = False
            elif token in precedence:
                op = "u-" if token == "-" and expect_operand else token
                while (operators and isinstance(operators[-1], str)
                       and (precedence[operators[-1]] > precedence[op]
                            or (precedence[operators[-1]] == precedence[op] and op != "u-"))):
                    reduce_operator()
                operators.append(op)
                expect_operand = True
            else:
                if i + 2 < len(tokens) and tokens[i + 1] == ":":
                    operands.append(("range", token, tokens[i + 2]))
                    i += 2
                else:
                    operands.append(("cell", token))
                expect_operand = False
            i += 1

        while operators:
            reduce_operator()
        return operands[0]

    expressions = {
        name: parse(content[1:]) if content.startswith("=")
        else ("number", int(content))
        for name, content in cells.items()
    }
    results = {}
    active = set()

    def evaluate(start):
        tasks = [("cell", start)]
        values = []

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                name = task[1]
                if name not in expressions:
                    values.append(0)
                elif name in results:
                    values.append(results[name])
                elif name in active:
                    values.append("#CYCLE!")
                else:
                    active.add(name)
                    tasks.append(("finish_cell", name))
                    tasks.append(("eval", expressions[name]))

            elif kind == "finish_cell":
                name = task[1]
                results[name] = values[-1]
                active.remove(name)

            elif kind == "eval":
                node = task[1]
                node_type = node[0]
                if node_type == "number":
                    values.append(node[1])
                elif node_type == "cell":
                    tasks.append(("cell", node[1]))
                elif node_type == "unary":
                    tasks.append(("unary",))
                    tasks.append(("eval", node[1]))
                elif node_type == "binary":
                    tasks.append(("binary_left", node[1], node[3]))
                    tasks.append(("eval", node[2]))
                else:
                    function, args = node[1], node[2]
                    if function == "IF":
                        comparison = args[0]
                        tasks.append(("if_left", comparison[1], comparison[3],
                                      args[1], args[2]))
                        tasks.append(("eval", comparison[2]))
                    else:
                        expanded = []
                        for arg in args:
                            if arg[0] != "range":
                                expanded.append(arg)
                                continue
                            first, last = arg[1], arg[2]
                            c1, c2 = sorted((ord(first[0]), ord(last[0])))
                            r1, r2 = sorted((int(first[1:]), int(last[1:])))
                            for row in range(r1, r2 + 1):
                                for col in range(c1, c2 + 1):
                                    name = chr(col) + str(row)
                                    if name in expressions:
                                        expanded.append(("cell", name))
                        tasks.append(("aggregate", function, expanded, 0, None))

            elif kind == "unary":
                value = values.pop()
                values.append(value if isinstance(value, str) else -value)

            elif kind == "binary_left":
                left = values.pop()
                if isinstance(left, str):
                    values.append(left)
                else:
                    tasks.append(("binary_right", task[1], left))
                    tasks.append(("eval", task[2]))

            elif kind == "binary_right":
                op, left = task[1], task[2]
                right = values.pop()
                if isinstance(right, str):
                    values.append(right)
                elif op == "+":
                    values.append(left + right)
                elif op == "-":
                    values.append(left - right)
                elif op == "*":
                    values.append(left * right)
                elif right == 0:
                    values.append("#DIV/0!")
                else:
                    quotient = abs(left) // abs(right)
                    values.append(-quotient if (left < 0) != (right < 0) else quotient)

            elif kind == "if_left":
                left = values.pop()
                if isinstance(left, str):
                    values.append(left)
                else:
                    tasks.append(("if_right", task[1], left, task[3], task[4]))
                    tasks.append(("eval", task[2]))

            elif kind == "if_right":
                op, left, then, otherwise = task[1:]
                right = values.pop()
                if isinstance(right, str):
                    values.append(right)
                else:
                    condition = {
                        "=": left == right,
                        "<>": left != right,
                        "<": left < right,
                        "<=": left <= right,
                        ">": left > right,
                        ">=": left >= right,
                    }[op]
                    tasks.append(("eval", then if condition else otherwise))

            elif kind == "aggregate":
                function, args, index, accumulated = task[1:]
                if index == len(args):
                    values.append(0 if accumulated is None else accumulated)
                else:
                    tasks.append(("aggregate_value", function, args, index, accumulated))
                    tasks.append(("eval", args[index]))

            elif kind == "aggregate_value":
                function, args, index, accumulated = task[1:]
                value = values.pop()
                if isinstance(value, str):
                    values.append(value)
                else:
                    if accumulated is None:
                        accumulated = value
                    elif function == "SUM":
                        accumulated += value
                    elif function == "MIN":
                        accumulated = min(accumulated, value)
                    else:
                        accumulated = max(accumulated, value)
                    tasks.append(("aggregate", function, args, index + 1, accumulated))

        return values.pop()

    for name in cells:
        if name not in results:
            evaluate(name)

    return {name: results[name] for name in cells}
